//! The monitoring backend's API and live-feed types, shared with the dashboard (TypeScript
//! generated by ts-rs). The backend itself (a Cloudflare Worker) imports the same bindings.

use serde::{Deserialize, Serialize};
use ts_rs::TS;

use crate::model::{CaptureFinding, CapturedStatement, FindingKind, FixHint, OriginCount, Orm, StatementKind, SuggestionSeverity};

/// An application: one or more backends (services) reporting to it, each with its own DSN.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct Project {
    pub id: String,
    pub name: String,
    /// Oldest first, disconnected ones included (their history is kept).
    pub backends: Vec<Backend>,
    pub settings: ProjectSettings,
    pub created_at: String,
}

/// One service of a project, connected through its own DSN.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct Backend {
    pub id: String,
    pub name: String,
    /// `https://<key>@<host>/<project id>`: what the SDK's `dsn` option takes. `None` once
    /// disconnected: its SDKs are refused, its history stays.
    pub dsn: Option<String>,
    /// The ORM recognised from its traffic so far.
    pub orm: Option<Orm>,
    pub created_at: String,
    /// When it last sent anything; `None` until it does.
    pub last_seen: Option<String>,
}

/// What a project flags and sends; SDKs receive it with every reply.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", default)]
#[ts(export)]
pub struct ProjectSettings {
    /// Statements slower than this are flagged, ms.
    pub slow_ms: f64,
    /// Executions in a row that make a loop (N+1).
    pub loop_min: u32,
    /// Statements in one request that make it chatty.
    pub chatty: u32,
    /// Rows that make a result large.
    pub large_rows: f64,
    /// Share of requests *without* problems the SDK sends anyway, for the live feed (0–1).
    pub live_sample_rate: f64,
}

impl Default for ProjectSettings {
    fn default() -> Self {
        Self { slow_ms: 100.0, loop_min: 5, chatty: 50, large_rows: 1000.0, live_sample_rate: 0.05 }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum IssueStatus {
    Unresolved,
    Resolved,
    /// Still counted, never reopened.
    Ignored,
}

/// One problem (a finding with a stable id) in one backend and environment, across every request
/// that showed it.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct Issue {
    pub id: i32,
    /// The backend it was found in: the same problem in two backends is two issues.
    pub backend: String,
    pub environment: String,
    pub kind: FindingKind,
    /// The highest seen.
    pub severity: SuggestionSeverity,
    pub title: String,
    /// The latest event's explanation.
    pub detail: String,
    /// The line of application code most often responsible.
    pub culprit: Option<String>,
    /// The request (route) or job it was last seen in.
    pub transaction: Option<String>,
    pub status: IssueStatus,
    /// Seen again after it was resolved.
    pub regressed: bool,
    /// Requests that showed it.
    pub times_seen: u32,
    /// Executions, loops or failures, summed over those requests.
    pub occurrences: u32,
    /// Statement time attributable to it, summed, ms.
    pub impact_ms: f64,
    pub first_seen: String,
    pub last_seen: String,
    pub first_release: Option<String>,
    pub last_release: Option<String>,
}

/// An issue with what's needed to fix it.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct IssueDetail {
    pub issue: Issue,
    pub fingerprint: String,
    /// As the SDK sent it: values replaced by `?` unless the app sends them.
    pub sample_sql: String,
    /// The statement whose rows an N+1 iterates.
    pub parent_sql: Option<String>,
    pub origins: Vec<OriginCount>,
    pub fix: Option<FixHint>,
    pub resolved_at: Option<String>,
}

/// One request that showed an issue, with every statement it ran.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct IssueEvent {
    pub id: i32,
    pub at: String,
    pub release: Option<String>,
    pub transaction: Option<String>,
    pub duration_ms: f64,
    pub finding: CaptureFinding,
    pub statements: Vec<CapturedStatement>,
}

/// A statement shape's totals over a period, from the SDKs' statistics.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct QueryShape {
    pub backend: String,
    pub fingerprint: String,
    pub sample_sql: String,
    pub kind: StatementKind,
    pub tables: Vec<String>,
    pub calls: u32,
    pub total_ms: f64,
    pub mean_ms: f64,
    pub max_ms: f64,
    pub errors: u32,
    pub rows: f64,
    pub last_seen: String,
}

/// A finding as the live feed shows it next to its request.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct LiveFinding {
    pub issue_id: i32,
    /// The statement shape it is about, to tie it to the request's statements.
    pub fingerprint: String,
    pub kind: FindingKind,
    pub severity: SuggestionSeverity,
    pub title: String,
}

/// A request an SDK sent (flagged, or sampled), as the backend keeps it for the query history.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct StoredRequest {
    /// Increasing within the project: newer requests have larger ids.
    pub id: i32,
    /// The backend that sent it.
    pub backend: String,
    pub environment: String,
    pub release: Option<String>,
    /// The route (`GET /orders/:id`) or job name.
    pub name: String,
    pub at: String,
    pub duration_ms: f64,
    pub db_ms: f64,
    pub statements: Vec<CapturedStatement>,
    pub findings: Vec<LiveFinding>,
}

/// Lines of application code around an `origin` (`file:line`), sent by SDKs with source
/// context on, so a fix can be written against the code that ran the statement.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct SourceSnippet {
    pub origin: String,
    /// The line number of `lines[0]`.
    pub first_line: u32,
    pub lines: Vec<String>,
}

/// What the dashboard's live view receives over its WebSocket.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(tag = "type", rename_all = "camelCase")]
#[ts(export)]
pub enum LiveEvent {
    /// A request an SDK sent, just stored.
    Transaction(StoredRequest),
    /// An issue was created, or came back after being resolved.
    #[serde(rename_all = "camelCase")]
    Issue { issue: Issue, regressed: bool },
    /// Totals of an SDK's statistics report: every statement, not just sent requests.
    #[serde(rename_all = "camelCase")]
    Throughput { backend: String, environment: String, at: String, period_ms: f64, calls: u32, total_ms: f64, errors: u32 },
}
